// Mirror of protocol/src/lib.rs (postcard). Keep in sync; golden vectors in test/vectors.json
// are generated by `cargo test --features std` in ../protocol and verified by vitest.
export const PROTO_VERSION = 1;

export type Telemetry =
  | { type: "status"; activeChannel: number; freeHeap: number; cpuLoad: number; dropped: number }
  | { type: "scan"; bssid: string; channel: number; rssi: number; ssid: string }
  | { type: "event"; code: number; message: string }
  | { type: "otaAck"; nextOffset: number };

export type Command =
  | { type: "startScan"; bandMask: number }
  | { type: "stop" }
  | { type: "configureRadio"; channel: number }
  | { type: "reboot" }
  | { type: "otaBegin"; size: number; sha256: Uint8Array }
  | { type: "otaChunk"; offset: number; data: Uint8Array }
  | { type: "otaEnd" };

class Reader {
  i = 2; // skip [ver][seq]
  constructor(readonly b: Uint8Array) {}
  u8(): number {
    if (this.i >= this.b.length) throw new Error("short packet");
    return this.b[this.i++];
  }
  i8(): number { const v = this.u8(); return v > 127 ? v - 256 : v; }
  varint(): number {
    let r = 0, shift = 0;
    for (;;) {
      const x = this.u8();
      r += (x & 0x7f) * 2 ** shift; // avoid 32-bit overflow of <<
      if (!(x & 0x80)) return r;
      shift += 7;
      if (shift > 35) throw new Error("varint too long");
    }
  }
  bytes(n: number): Uint8Array {
    if (this.i + n > this.b.length) throw new Error("short packet");
    const s = this.b.subarray(this.i, this.i + n);
    this.i += n;
    return s;
  }
  str(): string { return new TextDecoder().decode(this.bytes(this.varint())); }
}

export function decodeTelemetry(buf: Uint8Array): { seq: number; msg: Telemetry } {
  if (buf.length < 2) throw new Error("short packet");
  if (buf[0] !== PROTO_VERSION) throw new Error(`bad protocol version ${buf[0]}`);
  const r = new Reader(buf);
  const tag = r.varint();
  let msg: Telemetry;
  switch (tag) {
    case 0: msg = { type: "status", activeChannel: r.u8(), freeHeap: r.varint(), cpuLoad: r.u8(), dropped: r.varint() }; break;
    case 1: {
      const bssid = [...r.bytes(6)].map((x) => x.toString(16).padStart(2, "0")).join(":");
      msg = { type: "scan", bssid, channel: r.u8(), rssi: r.i8(), ssid: r.str() };
      break;
    }
    case 2: msg = { type: "event", code: r.varint(), message: r.str() }; break;
    case 3: msg = { type: "otaAck", nextOffset: r.varint() }; break;
    default: throw new Error(`unknown telemetry tag ${tag}`);
  }
  return { seq: buf[1], msg };
}

function varint(n: number): number[] {
  const o: number[] = [];
  do { let b = n % 128; n = Math.floor(n / 128); if (n) b |= 0x80; o.push(b); } while (n);
  return o;
}

export function encodeCommand(seq: number, c: Command): Uint8Array<ArrayBuffer> {
  const o: number[] = [PROTO_VERSION, seq & 0xff];
  switch (c.type) {
    case "startScan": o.push(0, c.bandMask); break;
    case "stop": o.push(1); break;
    case "configureRadio": o.push(2, c.channel); break;
    case "reboot": o.push(3); break;
    case "otaBegin":
      if (c.sha256.length !== 32) throw new Error("sha256 must be 32 bytes");
      o.push(4, ...varint(c.size), ...c.sha256); break;
    case "otaChunk":
      if (c.data.length > 96) throw new Error("chunk > 96 bytes");
      o.push(5, ...varint(c.offset), ...varint(c.data.length), ...c.data); break;
    case "otaEnd": o.push(6); break;
  }
  return Uint8Array.from(o);
}
